// Tests for the VP8 keyframe decoders against REAL lossy streams (TestData/Vp8Lossy, generated by
// scripts/images/make_vp8_lossy_fixtures.py).
//
// Fixtures: raw VP8 keyframes (the payload of a WebP 'VP8 ' chunk or an IVF frame) written by libwebp (Pillow + cwebp:
// quality 1..100, methods 0..6, 4 segments, simple and normal loop filter, sharpness 0..7, filter strength 0..100) and by
// libvpx (token partitions 2/4/8, versions 0..3, mode/ref loop-filter deltas), sizes 1x1 .. 640x480.
// THE TRUTH IS NEVER OUR OWN CODE: <name>.yuv (or .sha256 for the larger pictures) is the output of ffmpeg's native VP8
// decoder (-c:v vp8, yuv420p, verified native), which the generator also checked against ffmpeg's webp decoder and libwebp's
// dwebp for every libwebp-made file. manifest.csv carries the header facts an independent python parser read out of each
// file, so these tests can assert the corpus covers each keyframe feature.
//
// Every test collects ALL failures with the fixture name and the first differing plane/byte before failing.

using System.Security.Cryptography;
using SpawnDev.Codecs.Video.Vp8;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string Vp8LossyPrefix = "SpawnDev.Codecs.Demo.Shared.TestData.Vp8Lossy.";

    private static string[] Vp8LossyFixtureNames()
    {
        var names = typeof(CodecsTestBase).Assembly.GetManifestResourceNames()
            .Where(n => n.StartsWith(Vp8LossyPrefix, StringComparison.Ordinal) && n.EndsWith(".vp8", StringComparison.Ordinal))
            .Select(n => n.Substring(Vp8LossyPrefix.Length, n.Length - Vp8LossyPrefix.Length - 4))
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();
        if (names.Length == 0) throw new InvalidOperationException("No VP8 lossy fixtures are embedded.");
        return names;
    }

    /// <summary>One manifest.csv row (header facts parsed by the generator's independent python parser).</summary>
    private sealed record Vp8LossyInfo(string Name, int Width, int Height, int Version, int FilterType, int FilterLevel,
        int Sharpness, bool LfDelta, bool Segmentation, int Log2Parts, int Q);

    private static List<Vp8LossyInfo> Vp8LossyManifest()
    {
        var text = System.Text.Encoding.UTF8.GetString(ReadEmbedded(Vp8LossyPrefix + "manifest.csv"));
        var rows = new List<Vp8LossyInfo>();
        foreach (var line in text.Split('\n').Skip(1))
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            var c = line.TrimEnd('\r').Split(',');
            rows.Add(new Vp8LossyInfo(c[0], int.Parse(c[2]), int.Parse(c[3]), int.Parse(c[4]), int.Parse(c[5]), int.Parse(c[6]),
                int.Parse(c[7]), c[8] == "1", c[10] == "1", int.Parse(c[16]), int.Parse(c[17])));
        }
        return rows;
    }

    /// <summary>
    /// Compares decoded planes against the fixture truth (the yuv file, or its SHA-256). Returns null when equal, else a
    /// description with the first differing plane and byte (the byte is only known when the full yuv is embedded; for the
    /// SHA-only pictures the caller adds a comparison against the CPU reference).
    /// </summary>
    private static string? CompareVp8Truth(string name, byte[] y, byte[] u, byte[] v, int width, int height)
    {
        var all = new byte[y.Length + u.Length + v.Length];
        Buffer.BlockCopy(y, 0, all, 0, y.Length);
        Buffer.BlockCopy(u, 0, all, y.Length, u.Length);
        Buffer.BlockCopy(v, 0, all, y.Length + u.Length, v.Length);
        int cw = (width + 1) / 2;
        if (HasEmbedded(Vp8LossyPrefix + name + ".yuv"))
        {
            var expected = ReadEmbedded(Vp8LossyPrefix + name + ".yuv");
            if (expected.Length != all.Length) return $"yuv length {all.Length} != expected {expected.Length}";
            for (int i = 0; i < expected.Length; i++)
            {
                if (expected[i] == all[i]) continue;
                string plane; int off, w;
                if (i < y.Length) { plane = "Y"; off = i; w = width; }
                else if (i < y.Length + u.Length) { plane = "U"; off = i - y.Length; w = cw; }
                else { plane = "V"; off = i - y.Length - u.Length; w = cw; }
                return $"first mismatch in {plane} plane at x={off % w} y={off / w}: got {all[i]}, expected {expected[i]}";
            }
            return null;
        }
        var expectedHash = System.Text.Encoding.ASCII.GetString(ReadEmbedded(Vp8LossyPrefix + name + ".sha256")).Trim();
        var hash = Convert.ToHexString(SHA256.HashData(all)).ToLowerInvariant();
        return hash == expectedHash ? null : $"sha256 {hash} != expected {expectedHash}";
    }

    [TestMethod(Category = "CpuOnly")]
    public void Vp8IntraPredictor4x4_VerticalLeft_LastTwoValuesFollowRfc6386()
    {
        CpuOnlyTest();
        // RFC 6386 B_VL_PRED: "the last two values do not strictly follow the pattern": B[2][3] = avg3(A4,A5,A6) and
        // B[3][3] = avg3(A5,A6,A7). The library had B[3][3] = avg3(A4,A5,A6), which only real lossy files exposed.
        var above = new byte[] { 0, 10, 20, 30, 40, 50, 60, 70, 80 };   // above[-1] = 0, above[0..7] = 10..80
        var left = new byte[4];
        var dst = new byte[16];
        Vp8IntraPredictor4x4.Predict(Vp8IntraMode4x4.BVlPred, above, 1, left, dst, 4);
        Equal((byte)((50 + 2 * 60 + 70 + 2) >> 2), dst[2 * 4 + 3], "B[2][3]");
        Equal((byte)((60 + 2 * 70 + 80 + 2) >> 2), dst[3 * 4 + 3], "B[3][3]");
        Equal((byte)((40 + 2 * 50 + 60 + 2) >> 2), dst[1 * 4 + 3], "B[1][3]");
    }

    [TestMethod(Category = "CpuOnly")]
    public void Vp8LossyFixtures_Manifest_CoversEveryKeyframeFeature()
    {
        CpuOnlyTest();
        // A corpus that silently stops covering a feature would make the decoder tests below meaningless.
        var rows = Vp8LossyManifest();
        var names = Vp8LossyFixtureNames();
        Equal(names.Length, rows.Count, "every .vp8 has a manifest row");
        True(rows.Count >= 90, $"only {rows.Count} fixtures");
        True(rows.Any(r => r.FilterType == 1 && r.FilterLevel > 0), "simple loop filter");
        True(rows.Any(r => r.FilterType == 0 && r.FilterLevel > 0), "normal loop filter");
        True(rows.Any(r => r.FilterLevel == 0), "loop filter level 0");
        True(rows.Count(r => r.Sharpness > 0 && r.FilterLevel > 0) >= 5, "sharpness > 0");
        True(rows.Any(r => r.LfDelta), "mode/ref loop filter deltas");
        True(rows.Any(r => r.Segmentation), "segmentation");
        for (int p = 1; p <= 3; p++) True(rows.Any(r => r.Log2Parts == p), $"{1 << p} token partitions");
        for (int v = 0; v <= 3; v++) True(rows.Any(r => r.Version == v), $"version {v}");
        True(rows.Any(r => r.Width == 1 && r.Height == 1), "1x1");
        True(rows.Any(r => r.Width % 16 != 0 && r.Height % 16 != 0), "non-multiple-of-16 sizes");
        True(rows.Any(r => r.Width >= 640 && r.Height >= 480), "640x480");
    }

    [TestMethod(Timeout = 600000, Category = "NotOnWebGL")]
    public async Task Vp8FullKeyframeDecoderGpu_AllFixtures_MatchFfmpeg_ManagedOverload()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new Vp8FullKeyframeDecoderGpu(acc);
            var failures = new List<string>();
            int count = 0;
            foreach (var name in Vp8LossyFixtureNames())
            {
                try
                {
                    var frame = ReadEmbedded(Vp8LossyPrefix + name + ".vp8");
                    var got = await dec.DecodeKeyFrameAsync(frame);
                    var diff = CompareVp8Truth(name, got.YPlane, got.UPlane, got.VPlane, got.Width, got.Height);
                    if (diff != null) failures.Add($"{name}: {diff}");
                    count++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(count >= 150, $"only {count} fixtures were exercised");
            True(failures.Count == 0, $"{failures.Count} of {Vp8LossyFixtureNames().Length} VP8 fixtures failed on the accelerator:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Timeout = 600000, Category = "NotOnWebGL")]
    public async Task Vp8FullKeyframeDecoderGpu_AllFixtures_MatchFfmpeg_ArrayViewOverload_IntoPoisonedBuffers()
    {
        // The accelerator-resident overload: frame already on the device (the buffer longer than the frame, garbage after it),
        // planes written into caller views pre-filled with 0xAB and longer than needed. A decoder that wrote short, past the
        // picture, or into the wrong plane leaves / disturbs 0xAB.
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new Vp8FullKeyframeDecoderGpu(acc);
            var failures = new List<string>();
            int count = 0;
            foreach (var name in Vp8LossyFixtureNames())
            {
                try
                {
                    var frame = ReadEmbedded(Vp8LossyPrefix + name + ".vp8");
                    using var dFile = acc.Allocate1D<byte>(frame.Length + 13);
                    var padded = new byte[dFile.Length];
                    System.Array.Fill(padded, (byte)0xEE);
                    System.Array.Copy(frame, padded, frame.Length);
                    DeviceTransfer.Upload(dFile.View, padded);

                    var tag = await dec.ReadFrameTagAsync(dFile.View);
                    int w = tag.Width!.Value, h = tag.Height!.Value;
                    long yLen = Vp8FullKeyframeDecoderGpu.GetLumaPlaneSize(w, h);
                    long cLen = Vp8FullKeyframeDecoderGpu.GetChromaPlaneSize(w, h);
                    using var dY = acc.Allocate1D<byte>(yLen + 9);
                    using var dU = acc.Allocate1D<byte>(cLen + 9);
                    using var dV = acc.Allocate1D<byte>(cLen + 9);
                    foreach (var b in new[] { dY, dU, dV })
                    {
                        var fill = new byte[b.Length];
                        System.Array.Fill(fill, (byte)0xAB);
                        DeviceTransfer.Upload(b.View, fill);
                    }
                    await dec.DecodeKeyFrameAsync(dFile.View, frame.Length, dY.View, dU.View, dV.View);
                    var y = await DeviceTransfer.DownloadAsync(dY.View, dY.Length);
                    var u = await DeviceTransfer.DownloadAsync(dU.View, dU.Length);
                    var v = await DeviceTransfer.DownloadAsync(dV.View, dV.Length);
                    bool tailOk = true;
                    for (int i = 0; i < 9; i++) tailOk &= y[yLen + i] == 0xAB && u[cLen + i] == 0xAB && v[cLen + i] == 0xAB;
                    if (!tailOk) failures.Add($"{name}: wrote past the end of a plane");
                    var diff = CompareVp8Truth(name, y.AsSpan(0, (int)yLen).ToArray(), u.AsSpan(0, (int)cLen).ToArray(),
                        v.AsSpan(0, (int)cLen).ToArray(), w, h);
                    if (diff != null) failures.Add($"{name}: {diff}");
                    count++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(count >= 150, $"only {count} fixtures were exercised");
            True(failures.Count == 0, $"{failures.Count} of {Vp8LossyFixtureNames().Length} VP8 fixtures failed (ArrayView1D overload):\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    private static int Vp8FirstPartSize(byte[] frame) => (frame[0] | (frame[1] << 8) | (frame[2] << 16)) >> 5;

    private static byte[] Vp8WithFirstPartSize(byte[] frame, int size)
    {
        var f = (byte[])frame.Clone();
        int tag = (f[0] | (f[1] << 8) | (f[2] << 16)) & 0x1F | (size << 5);
        f[0] = (byte)tag; f[1] = (byte)(tag >> 8); f[2] = (byte)(tag >> 16);
        return f;
    }

    private static byte[] Vp8Prefix(byte[] frame, int length) => frame.AsSpan(0, length).ToArray();

    [TestMethod(Category = "BrowserOnly,NotOnWebGL")]
    public async Task Vp8FullKeyframeDecoderGpu_TypedArrayOverload_MatchesFfmpeg()
    {
        if (!OperatingSystem.IsBrowser())
            throw new UnsupportedTestException("TypedArray overloads need a browser accelerator.");
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new Vp8FullKeyframeDecoderGpu(acc);
            await RunVp8FullTypedArrayDecode(dec);
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [System.Runtime.Versioning.SupportedOSPlatform("browser")]
    private static async Task RunVp8FullTypedArrayDecode(Vp8FullKeyframeDecoderGpu dec)
    {
        var failures = new List<string>();
        foreach (var name in new[] { "pil_text_17x33_q75_m4", "cw_strong_f80_s3_photo_100x75", "vpx_slices4_photo_255x129", "pil_photo_1x1_q1_m0" })
        {
            var data = ReadEmbedded(Vp8LossyPrefix + name + ".vp8");
            using var js = new SpawnDev.SpawnJS.JSObjects.Uint8Array(data.Length);
            js.Set(data);
            using var frame = await dec.DecodeKeyFrameAsync(js);
            // Reading back to .NET is the TEST's terminal compare, not the product path.
            var diff = CompareVp8Truth(name, frame.YPlane.ReadBytes(), frame.UPlane.ReadBytes(), frame.VPlane.ReadBytes(), frame.Width, frame.Height);
            if (diff != null) failures.Add($"{name}: {diff}");
        }
        True(failures.Count == 0, string.Join("\n", failures));
    }

    [TestMethod(Category = "CpuOnly")]
    public void Vp8FullKeyframeDecoderGpu_WavefrontSchedule_RespectsEveryDependency()
    {
        CpuOnlyTest();
        // The CPU backend runs the threads of one launch in index order, which hides a wrong wavefront; the GPU backends do
        // not. So the schedule itself is checked: for every macroblock, its left, top, top-left and top-right neighbours
        // (the pixels reconstruction and the loop filter read or modify) are on EARLIER diagonals; macroblocks sharing a
        // diagonal are at least two columns apart (disjoint footprints); and the launches cover every macroblock exactly once.
        var failures = new List<string>();
        foreach (var (cols, rows) in new[] { (1, 1), (1, 5), (2, 2), (3, 7), (7, 3), (16, 9), (40, 30) })
        {
            var seen = new int[rows, cols];
            for (int d = 0; d < Vp8FullKeyframeDecoderGpu.GetWaveCount(cols, rows); d++)
            {
                Vp8FullKeyframeDecoderGpu.GetWaveRows(d, cols, rows, out int rowLo, out int count);
                int prevCol = -10;
                for (int k = 0; k < count; k++)
                {
                    int r = rowLo + k;
                    int c = d - (Vp8FullKeyframeDecoderGpu.WaveDiagonal(r, 0));
                    if (r < 0 || r >= rows || c < 0 || c >= cols) { failures.Add($"{cols}x{rows}: diagonal {d} lists ({r},{c}) outside the grid"); continue; }
                    if (Vp8FullKeyframeDecoderGpu.WaveDiagonal(r, c) != d) failures.Add($"{cols}x{rows}: ({r},{c}) not on diagonal {d}");
                    seen[r, c]++;
                    if (k > 0 && Math.Abs(c - prevCol) < 2) failures.Add($"{cols}x{rows}: diagonal {d} has macroblocks {prevCol} and {c} within 2 columns");
                    prevCol = c;
                    foreach (var (dr, dc) in new[] { (0, -1), (-1, 0), (-1, -1), (-1, 1) })
                    {
                        int nr = r + dr, nc = c + dc;
                        if (nr < 0 || nc < 0 || nc >= cols) continue;
                        if (Vp8FullKeyframeDecoderGpu.WaveDiagonal(nr, nc) >= d)
                            failures.Add($"{cols}x{rows}: ({r},{c}) on diagonal {d} depends on ({nr},{nc}) on diagonal {Vp8FullKeyframeDecoderGpu.WaveDiagonal(nr, nc)}");
                    }
                }
            }
            for (int r = 0; r < rows; r++)
                for (int c = 0; c < cols; c++)
                    if (seen[r, c] != 1) failures.Add($"{cols}x{rows}: macroblock ({r},{c}) scheduled {seen[r, c]} times");
        }
        True(failures.Count == 0, string.Join("\n", failures.Take(20)));
    }

    [TestMethod(Category = "NotOnWebGL")]
    public async Task Vp8FullKeyframeDecoderGpu_HostileInputs_ThrowTheSpecificReason()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new Vp8FullKeyframeDecoderGpu(acc);
            var single = ReadEmbedded(Vp8LossyPrefix + "cw_strong_f80_s3_photo_100x75.vp8");     // 1 token partition
            var quad = ReadEmbedded(Vp8LossyPrefix + "vpx_slices4_photo_255x129.vp8");            // 4 token partitions
            var octo = ReadEmbedded(Vp8LossyPrefix + "vpx_slices8_text_255x129.vp8");             // 8 token partitions
            int p0 = Vp8FirstPartSize(single);
            int q0 = Vp8FirstPartSize(quad);
            int o0 = Vp8FirstPartSize(octo);

            // sizes of the first (n - 1) partitions of a multi-partition frame
            static int[] PartSizes(byte[] f, int firstPart, int n)
            {
                var s = new int[n - 1];
                for (int i = 0; i < n - 1; i++)
                {
                    int t = 10 + firstPart + 3 * i;
                    s[i] = f[t] | (f[t + 1] << 8) | (f[t + 2] << 16);
                }
                return s;
            }
            int quadBeforeLast = 3 * 3 + PartSizes(quad, q0, 4).Sum();      // bytes of table + partitions 0..2
            int octoBeforeLast = 3 * 7 + PartSizes(octo, o0, 8).Sum();

            var cases = new List<(string label, byte[] data, Vp8DecodeError expected)>();
            cases.Add(("empty", System.Array.Empty<byte>(), Vp8DecodeError.TooShort));
            cases.Add(("9 bytes", Vp8Prefix(single, 9), Vp8DecodeError.TooShort));
            var inter = (byte[])single.Clone(); inter[0] |= 1;
            cases.Add(("inter frame", inter, Vp8DecodeError.NotKeyFrame));
            var badSc = (byte[])single.Clone(); badSc[4] ^= 0xFF;
            cases.Add(("bad start code", badSc, Vp8DecodeError.BadStartCode));
            var zw = (byte[])single.Clone(); zw[6] = 0; zw[7] = 0;
            cases.Add(("zero width", zw, Vp8DecodeError.ZeroSize));
            var zh = (byte[])single.Clone(); zh[8] = 0; zh[9] = 0;
            cases.Add(("zero height", zh, Vp8DecodeError.ZeroSize));
            var v4 = (byte[])single.Clone(); v4[0] = (byte)((v4[0] & ~0x0E) | (4 << 1));
            cases.Add(("version 4", v4, Vp8DecodeError.UnsupportedVersion));
            cases.Add(("first partition cut", Vp8Prefix(single, 10 + p0 - 1), Vp8DecodeError.FirstPartitionExceedsFrame));
            cases.Add(("first partition declared too small", Vp8WithFirstPartSize(single, 12), Vp8DecodeError.FirstPartitionTruncated));
            cases.Add(("first partition declared too small (modes)", Vp8WithFirstPartSize(single, p0 / 2), Vp8DecodeError.FirstPartitionTruncated));
            cases.Add(("no token bytes at all", Vp8Prefix(single, 10 + p0), Vp8DecodeError.TokenPartitionTruncated));
            cases.Add(("half of the tokens", Vp8Prefix(single, 10 + p0 + (single.Length - 10 - p0) / 2), Vp8DecodeError.TokenPartitionTruncated));
            cases.Add(("4 partitions: cut inside the size table", Vp8Prefix(quad, 10 + q0 + 4), Vp8DecodeError.PartitionTableTruncated));
            var bigSize = (byte[])quad.Clone(); bigSize[10 + q0] = 0xFF; bigSize[10 + q0 + 1] = 0xFF; bigSize[10 + q0 + 2] = 0x7F;
            cases.Add(("4 partitions: partition 0 declares 8 MB", bigSize, Vp8DecodeError.TokenPartitionExceedsFrame));
            cases.Add(("4 partitions: last partition cut in half",
                Vp8Prefix(quad, 10 + q0 + quadBeforeLast + (quad.Length - 10 - q0 - quadBeforeLast) / 2), Vp8DecodeError.TokenPartitionTruncated));
            cases.Add(("8 partitions: cut inside the size table", Vp8Prefix(octo, 10 + o0 + 20), Vp8DecodeError.PartitionTableTruncated));
            cases.Add(("8 partitions: last partition cut in half",
                Vp8Prefix(octo, 10 + o0 + octoBeforeLast + (octo.Length - 10 - o0 - octoBeforeLast) / 2), Vp8DecodeError.TokenPartitionTruncated));
            cases.Add(("8 partitions: last partition empty", Vp8Prefix(octo, 10 + o0 + octoBeforeLast), Vp8DecodeError.TokenPartitionTruncated));

            var failures = new List<string>();
            foreach (var (label, data, expected) in cases)
            {
                try
                {
                    await dec.DecodeKeyFrameAsync(data);
                    failures.Add($"{label}: decoded without error, expected {expected}");
                }
                catch (Vp8DecodeException ex)
                {
                    if (ex.Error != expected) failures.Add($"{label}: got {ex.Error} ({ex.Message}), expected {expected}");
                }
                catch (Exception ex)
                {
                    failures.Add($"{label}: {ex.GetType().Name}: {ex.Message} (expected Vp8DecodeException {expected})");
                }
            }

            // The same decoder instance still works after every error.
            var good = await dec.DecodeKeyFrameAsync(single);
            var diff = CompareVp8Truth("cw_strong_f80_s3_photo_100x75", good.YPlane, good.UPlane, good.VPlane, good.Width, good.Height);
            if (diff != null) failures.Add($"decode after the errors: {diff}");
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Timeout = 600000, Category = "NotOnWebGL")]
    public async Task Vp8FullKeyframeDecoderGpu_RandomCorruption_NeverHangsOrThrowsAnythingElse()
    {
        // Flip bytes, truncate, and splice random data into real frames: every outcome must be a normal decode (garbage
        // pixels are fine for a corrupt stream) or a Vp8DecodeException, never another exception type, never a hang.
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new Vp8FullKeyframeDecoderGpu(acc);
            var rng = new Random(20261022);
            var names = new[] { "cw_strong_f80_s3_photo_100x75", "vpx_slices4_photo_255x129", "rnd_10_128x96_simple_L63_S4_P2_delta_seg",
                                "pil_noise_17x33_q50_m3", "vpx_p1_simple_photo_100x75" };
            int ok = 0, errors = 0;
            var failures = new List<string>();
            foreach (var name in names)
            {
                var original = ReadEmbedded(Vp8LossyPrefix + name + ".vp8");
                for (int trial = 0; trial < 24; trial++)
                {
                    var data = (byte[])original.Clone();
                    int mode = trial % 4;
                    if (mode == 0)
                    {
                        for (int k = 0; k < 1 + trial; k++) data[10 + rng.Next(data.Length - 10)] ^= (byte)(1 << rng.Next(8));
                    }
                    else if (mode == 1)
                    {
                        data = Vp8Prefix(data, 10 + rng.Next(data.Length - 10));
                    }
                    else if (mode == 2)
                    {
                        int from = 10 + rng.Next(data.Length - 10);
                        for (int i = from; i < Math.Min(data.Length, from + 64); i++) data[i] = (byte)rng.Next(256);
                    }
                    else
                    {
                        for (int i = 10; i < data.Length; i++) data[i] = (byte)rng.Next(256);          // all random after the tag
                    }
                    try
                    {
                        var got = await dec.DecodeKeyFrameAsync(data);
                        if (got.YPlane.Length != Vp8FullKeyframeDecoderGpu.GetLumaPlaneSize(got.Width, got.Height))
                            failures.Add($"{name} trial {trial}: wrong plane size");
                        ok++;
                    }
                    catch (Vp8DecodeException) { errors++; }
                    catch (Exception ex) { failures.Add($"{name} trial {trial} (mode {mode}): {ex.GetType().Name}: {ex.Message}"); }
                }
            }
            True(ok > 0 && errors > 0, $"the corruption set should produce both outcomes (ok {ok}, errors {errors})");
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Category = "CpuOnly")]
    public void Vp8LossyFixtures_CpuReference_MatchesFfmpeg_AllFixtures()
    {
        CpuOnlyTest();
        // The reference walker + Vp8LoopFilter against ffmpeg's decode of the SAME bytes.
        var failures = new List<string>();
        foreach (var name in Vp8LossyFixtureNames())
        {
            try
            {
                var frame = ReadEmbedded(Vp8LossyPrefix + name + ".vp8");
                var planes = Vp8KeyframeReference.Decode(frame);
                var diff = CompareVp8Truth(name, planes.Y, planes.U, planes.V, planes.Width, planes.Height);
                if (diff != null) failures.Add($"{name}: {diff}");
            }
            catch (Exception ex)
            {
                failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
            }
        }
        True(failures.Count == 0, $"{failures.Count} of {Vp8LossyFixtureNames().Length} VP8 fixtures failed:\n" + string.Join("\n", failures));
    }
}
